package com.sekai.world.simulation.model;

public class EventTemplate {
    private Long id; private Long worldId; private String code; private String name; private String description; private Integer probabilityPercent; private Integer priority; private Boolean enabled; private String choicePositiveLabel; private Integer choicePositiveMoodDelta; private String choiceNegativeLabel; private Integer choiceNegativeMoodDelta;
    public EventTemplate() {} public EventTemplate(Long id,Long worldId,String code,String name,String description,Integer probabilityPercent,Integer priority,Boolean enabled,String choicePositiveLabel,Integer choicePositiveMoodDelta,String choiceNegativeLabel,Integer choiceNegativeMoodDelta){this.id=id;this.worldId=worldId;this.code=code;this.name=name;this.description=description;this.probabilityPercent=probabilityPercent;this.priority=priority;this.enabled=enabled;this.choicePositiveLabel=choicePositiveLabel;this.choicePositiveMoodDelta=choicePositiveMoodDelta;this.choiceNegativeLabel=choiceNegativeLabel;this.choiceNegativeMoodDelta=choiceNegativeMoodDelta;}
    public Long getId(){return id;} public void setId(Long v){id=v;} public Long getWorldId(){return worldId;} public void setWorldId(Long v){worldId=v;} public String getCode(){return code;} public void setCode(String v){code=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public Integer getProbabilityPercent(){return probabilityPercent;} public void setProbabilityPercent(Integer v){probabilityPercent=v;} public Integer getPriority(){return priority;} public void setPriority(Integer v){priority=v;} public Boolean getEnabled(){return enabled;} public void setEnabled(Boolean v){enabled=v;} public String getChoicePositiveLabel(){return choicePositiveLabel;} public void setChoicePositiveLabel(String v){choicePositiveLabel=v;} public Integer getChoicePositiveMoodDelta(){return choicePositiveMoodDelta;} public void setChoicePositiveMoodDelta(Integer v){choicePositiveMoodDelta=v;} public String getChoiceNegativeLabel(){return choiceNegativeLabel;} public void setChoiceNegativeLabel(String v){choiceNegativeLabel=v;} public Integer getChoiceNegativeMoodDelta(){return choiceNegativeMoodDelta;} public void setChoiceNegativeMoodDelta(Integer v){choiceNegativeMoodDelta=v;}
    public Long id(){return id;} public Long worldId(){return worldId;} public String code(){return code;} public String name(){return name;} public String description(){return description;} public Integer probabilityPercent(){return probabilityPercent;} public Integer priority(){return priority;} public Boolean enabled(){return enabled;} public String choicePositiveLabel(){return choicePositiveLabel;} public Integer choicePositiveMoodDelta(){return choicePositiveMoodDelta;} public String choiceNegativeLabel(){return choiceNegativeLabel;} public Integer choiceNegativeMoodDelta(){return choiceNegativeMoodDelta;}
}
